  evidence_code_sha TEXT NOT NULL,
  incumbent_model_id TEXT NOT NULL,
  challenger_model_id TEXT NOT NULL,
  selected_research_model_id TEXT NOT NULL,
  v2_probability REAL,
  v31_probability REAL,
