  close_timestamp TEXT,
  realized_result TEXT,
  clv_probability REAL,
  simulated_profit_units REAL,
  simulated_roi REAL,
  market_history_available INTEGER NOT NULL DEFAULT 0,
  market_unavailable_reason TEXT,
